param([Parameter(Mandatory)][string]$Source,[Parameter(Mandatory)][string]$OutDir,[string[]]$Only=@())
$ErrorActionPreference='Stop'
$ProgressPreference='SilentlyContinue'
if($env:COMPUTERNAME -cne 'CS2-GEN4'){throw 'Wrong fixture computer'}
$frame='C:\Windows\Temp\roo-industries-percent-folders'
if([IO.File]::ReadAllText((Join-Path $frame 'fixture-owner.txt')) -cne "Roo Industries percent folders owned scratch`r`n"){throw 'Wrong fixture owner'}
foreach($p in @($frame,(Split-Path $frame -Parent),'C:\Windows','C:\')){if((Get-Item -LiteralPath $p).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Reparse ancestry'}}
foreach($ace in (Get-Acl -LiteralPath $frame).Access){$sid=$ace.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value;if($ace.AccessControlType -eq 'Allow' -and $sid -notin 'S-1-5-18','S-1-5-32-544' -and ([int]$ace.FileSystemRights -band 278)){throw 'Scratch allows non-admin writes'}}
if((Split-Path ([IO.Path]::GetFullPath($OutDir)) -Parent) -ine $frame -or (Split-Path $OutDir -Leaf) -notmatch '^ui-ownership-[0-9a-f]{32}$' -or (Test-Path -LiteralPath $OutDir)){throw 'Expected fresh GUID fixture'}
[IO.Directory]::CreateDirectory($OutDir)|Out-Null
$compile=Join-Path $OutDir 'compile';[IO.Directory]::CreateDirectory($compile)|Out-Null;$env:TEMP=$compile;$env:TMP=$compile
function Guard { $k=[Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Software');try{ConvertTo-Json -InputObject @($k.GetValueNames()|Sort-Object|ForEach-Object {@{name=$_;kind=[string]$k.GetValueKind($_);value=$k.GetValue($_,$null,'DoNotExpandEnvironmentNames')}}) -Depth 30 -Compress}finally{$k.Dispose()} }
$guardBefore=Guard
$private='Software\RooIndustriesUiOwnership_'+[Guid]::NewGuid().ToString('N')
$root=[Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($private)
$results=[Collections.Generic.List[object]]::new()
$fixtureTasks=[Collections.Generic.List[string]]::new()
function Assert([bool]$Ok,[string]$Text){if(-not$Ok){throw $Text}}
function Refuses([scriptblock]$Body){$refused=$false;try{&$Body}catch{$refused=$true;Add-Content -LiteralPath (Join-Path $OutDir 'refusals.log') -Value $_.Exception.Message};Assert $refused 'Expected refusal'}
function Case([string]$Name,[scriptblock]$Body){if($Only.Count -and $Name -notin $Only){return};try{&$Body;Assert ((Guard) -ceq $guardBefore) 'HKCU Software root changed';$results.Add(@{name=$Name;passed=$true});'PASS '+$Name}catch{$results.Add(@{name=$Name;passed=$false;error=$_.Exception.Message});'FAIL '+$Name+' :: '+$_.Exception.Message}}
function Load-Function([string]$File,[string]$Name){$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $Source $File),[ref]$tokens,[ref]$errors);Assert ($errors.Count -eq 0) ('Parse '+$File);$f=@($ast.FindAll({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -ceq $Name},$true));Assert ($f.Count -eq 1) ('Function '+$Name);. ([scriptblock]::Create($f[0].Extent.Text));Set-Item -Path ('Function:script:'+ $Name) -Value (Get-Item ('Function:'+ $Name)).ScriptBlock}
function Log([string]$Text){Add-Content -LiteralPath (Join-Path $OutDir 'entry-path.log') -Value $Text}

function Read-FixtureText([string]$Path) {
 $stream=[IO.FileStream]::new($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::Read -bor [IO.FileShare]::Delete))
 $reader=[IO.StreamReader]::new($stream)
 try{$reader.ReadToEnd()}finally{$reader.Dispose()}
}

function Test-ParentCompletion([int]$ExitCode,[switch]$AlreadyFinished) {
 $tokens=$null;$errors=$null
 $ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $Source 'Invoke-LoadTimes.ps1'),[ref]$tokens,[ref]$errors)
 Assert ($errors.Count -eq 0) 'Parent parser failed'
 $outer=@($ast.FindAll({param($n)$n -is [Management.Automation.Language.TryStatementAst] -and $n.Finally -and $n.Finally.Extent.Text.Contains('Report-UnownedLoadTimesResources')},$true))[0]
 $statements=@($outer.Body.Statements);$first=-1
 for($i=0;$i -lt $statements.Count;$i++){if($statements[$i].Extent.Text -match '^\$done\s*='){$first=$i;break}}
 Assert ($first -ge 0) 'Actual parent completion entry absent'
 $body=[scriptblock]::Create(($statements[$first..($statements.Count-1)].Extent.Text -join "`n"))
 $out=Join-Path $OutDir ('parent-completion-'+$ExitCode+'-'+[bool]$AlreadyFinished);[IO.Directory]::CreateDirectory($out)|Out-Null
 $Scenario='modes';$scenarioScript='fixture';$Minutes=1;$script:ChildCompleted=$false;$script:PersistentResources=$null
 $done=Join-Path $out 'modes.done'
 $task='RooIndustries_UiOwnership_'+[Guid]::NewGuid().ToString('N');$fixtureTasks.Add($task)
 $code="[IO.File]::WriteAllText('"+$done.Replace("'","''")+"','x'); Start-Sleep -Seconds 3; exit "+$ExitCode
 $encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($code))
 $taskReceipt=Register-OwnedProbeTask $task (Join-Path ([Environment]::SystemDirectory) 'WindowsPowerShell\v1.0\powershell.exe') ('-NoProfile -NonInteractive -EncodedCommand '+$encoded) $out 'S-1-5-18' 1 5
 try{
  Start-ScheduledTask -TaskName $task
  $ready=(Get-Date).AddSeconds(20)
  while(-not(Test-Path -LiteralPath $done) -and (Get-Date) -lt $ready){Start-Sleep -Milliseconds 25}
  Assert (Test-Path -LiteralPath $done) 'Private child did not write done'
  $initial=Get-ScheduledTaskInfo -TaskName $task
  Assert ((Get-ScheduledTask -TaskName $task).State -eq 'Running') 'The exact done-before-exit ordering was not established'
  if($AlreadyFinished){$deadline=(Get-Date).AddSeconds(10);while((Get-ScheduledTask -TaskName $task).State -eq 'Running' -and (Get-Date) -lt $deadline){Start-Sleep -Milliseconds 50};Assert ((Get-ScheduledTaskInfo -TaskName $task).LastTaskResult -eq $ExitCode) 'Completed child result was not established'}
  $watch=[Diagnostics.Stopwatch]::StartNew();$refused=$false
  try{. $body}catch{$refused=$true;Log $_.Exception.Message}
  $final=Get-ScheduledTaskInfo -TaskName $task
  @{exit=$ExitCode;initialLastResult=$initial.LastTaskResult;finalLastResult=$final.LastTaskResult;elapsedMs=$watch.ElapsedMilliseconds;completed=$script:ChildCompleted;refused=$refused}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $out 'proof.json')
  if($ExitCode -eq 0){Assert ($script:ChildCompleted -and -not$refused -and $final.LastTaskResult -eq 0) 'Parent did not wait for successful child exit'}
  else{Assert ($refused -and -not$script:ChildCompleted -and $final.LastTaskResult -eq $ExitCode) 'Parent accepted a nonzero child exit with done'}
 }finally{Remove-OwnedTask $taskReceipt}
}

function Test-EntryFileCollision([string]$File,[string]$Variable,[string]$Leaf) {
 $path=Join-Path $OutDir $Leaf
 [IO.File]::WriteAllText($path,'foreign fixture bytes')
 Set-Variable -Name $Variable -Value $path
 $tokens=$null;$errors=$null
 $ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $Source $File),[ref]$tokens,[ref]$errors)
 Assert ($errors.Count -eq 0) ('Parser '+$File)
 $matches=@($ast.FindAll({param($n)$n -is [Management.Automation.Language.AssignmentStatementAst] -or $n -is [Management.Automation.Language.PipelineAst]},$true)|Where-Object {$_.Extent.Text -notmatch "[\r\n]" -and $_.Extent.Text -match '(Set-Content|Copy-Item|Copy-OwnedProbe|New-OwnedTextFile)' -and $_.Extent.Text -match ('\$'+[regex]::Escape($Variable)+'\b')}|Sort-Object {$_.Extent.Text.Length} -Descending)
 Assert ($matches.Count -gt 0) ('Actual fixture writer absent '+$File+' '+$Variable)
 $refused=$false
 try{. ([scriptblock]::Create($matches[0].Extent.Text))}catch{$refused=$true;Log $_.Exception.Message}
 Assert ($refused -and [IO.File]::ReadAllText($path) -ceq 'foreign fixture bytes') ('Actual fixture writer overwrote '+$Leaf)
}

